// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1e30);

        // actor deposits `amount` via the fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okDeposit);
        assertEq(c.balances(actor), amount);

        // actor withdraws
        vm.prank(actor);
        c.withdraw();

        // General rule: a completed withdraw() transfers the whole credited
        // balance out, so the contract holds no ether of the caller.
        assertTrue(address(c).balance == 0);
    }
}
